/* ---------------- geometry ---------------- */
const N = 22, C = 11, TW = 64, TH = 32, ZU = 18, OX = 720, OY = 170, RC = 3.4, Q = Math.PI / 2;

const FS = 27, FOY = 545; // top view: scale (px per world unit) and plan centre
const geo = (ang, flat) => {
  const c = Math.cos(ang), s = Math.sin(ang);
  const R = (x, y) => { const dx = x - C, dy = y - C; return [C + dx * c - dy * s, C + dx * s + dy * c]; };
  const P = flat ? (x, y, z = 0) => { const [a, b] = R(x, y); return [OX + (a - C) * FS, FOY + (b - C) * FS - z * 9]; } : (x, y, z = 0) => { const [a, b] = R(x, y); return [OX + ((a - b) * TW) / 2, OY + ((a + b) * TH) / 2 - z * ZU]; };
  const dep = (x, y) => { const [a, b] = R(x, y); return a + b; };
  const rn = (nx, ny) => [nx * c - ny * s, nx * s + ny * c];
  return { P, dep, rn, flat: !!flat };
};
const shade = (hex, f) => {
  const n = parseInt(hex.slice(1), 16);
  return "rgb(" + [(n >> 16) & 255, (n >> 8) & 255, n & 255].map((v) => Math.min(255, Math.round(v * f))).join(",") + ")";
};
const pts = (a) => a.map((p) => p[0].toFixed(1) + "," + p[1].toFixed(1)).join(" ");
const lightT = (nx, ny) => { const L = Math.hypot(nx, ny) || 1; return ((ny - nx) / (L * Math.SQRT2)) * 0.5 + 0.5; };
const MONO = "'Space Mono', ui-monospace, Menlo, monospace";
