const ROWS = ["Here & now", "Near term", "Emerging", "Future unlock"];
const TAGS = {
  "d1-01": [2, 3], "d1-02": [2, 0], "d1-03": [0, 3], "d1-04": [1, 2], "d1-05": [0, 1], "d1-06": [3, 1], "d1-07": [3, 0], "d1-08": [3, 1],
  "d1-09": [2, 2], "d1-10": [1, 2], "d1-11": [1, 3], "d1-12": [3, 0], "d1-13": [2, 1],
  "d2-01": [0, 0], "d2-02": [2, 2], "d2-03": [0, 3], "d2-04": [3, 2], "d2-05": [2, 0], "d2-06": [1, 1], "d2-07": [2, 3], "d2-08": [1, 1], "d2-09": [2, 1], "d2-10": [3, 0],
};
const ACC = [BR.teal, BR.vio, BR.mag, BR.org];      // wall colour: cool (tech) to warm (craft)
const CELL = 3.9, GUT = 0.8, G0 = 2, STEP = CELL + GUT, PLAZA_R = 4.0, KEEP = 5.4;
const cellX = (c) => G0 + c * STEP;
const cellY = (r) => G0 + (3 - r) * STEP;                       // future unlocks sit towards the back (up-right edge)
const mix = (a, b, t) => { const x = parseInt(a.slice(1), 16), y = parseInt(b.slice(1), 16); const m = (s) => Math.round(((x >> s) & 255) * (1 - t) + ((y >> s) & 255) * t); return "#" + ((1 << 24) | (m(16) << 16) | (m(8) << 8) | m(0)).toString(16).slice(1); };
const TOP = { Keynote: 2.9, Talk: 1.6, "Lightning talk": 0.9 };
const SLOTS = { 1: [[1.95, 1.95]], 2: [[1.2, 1.2], [2.7, 2.7]], 3: [[1.1, 1.1], [2.8, 1.3], [1.9, 2.8]] };

// One continuous island: each talk starts at its grid cell, then a small relaxation keeps it off the plaza, roads and neighbours.
// All 23 talks are shown; talks without a speaker photo yet show initials in the card. To hide them instead: SESSIONS.filter((s) => photoFor(s.speaker)).
const SHOWN = SESSIONS;

/* ---------------- abstract avatars (shapes generated from a name, so nobody's photo is used) ---------------- */
const hash32 = (str) => { let h = 2166136261; for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
const AV_COL = ["#dc258a", "#6103d1", "#f4620a", "#12b5f0", "#e8b020", "#3aa66b", "#fdf0dc"];
function avatarSpec(seed) {
  let h = hash32(seed || "x") || 1;
  const rnd = () => { h ^= h << 13; h >>>= 0; h ^= h >>> 17; h ^= h << 5; h >>>= 0; return h / 4294967296; };
  const pick = (a) => a[Math.floor(rnd() * a.length)];
  const bg = pick(["#17112b", "#2a1a63", "#4a0f3a", "#0f2f45"]), cols = AV_COL, shapes = [];
  for (let i = 0; i < 3; i++) shapes.push({ k: pick(["circle", "half", "bar", "tri", "ring"]), c: pick(cols), x: 22 + rnd() * 56, y: 22 + rnd() * 56, s: 26 + rnd() * 30, r: Math.floor(rnd() * 4) * 90 + (rnd() < 0.5 ? 0 : 45) });
  return { bg, shapes };
}
function AvInner({ seed, cid }) {
  const { bg, shapes } = avatarSpec(seed);
  return (
    <g>
      <clipPath id={cid}><circle cx="50" cy="50" r="50" /></clipPath>
      <g clipPath={"url(#" + cid + ")"}>
        <rect width="100" height="100" fill={bg} />
        {shapes.map((q, i) => {
          const t = `translate(${q.x} ${q.y}) rotate(${q.r})`, r = q.s / 2;
          if (q.k === "circle") return <circle key={i} cx={q.x} cy={q.y} r={r} fill={q.c} />;
          if (q.k === "ring") return <circle key={i} cx={q.x} cy={q.y} r={r * 0.8} fill="none" stroke={q.c} strokeWidth="7" />;
          if (q.k === "half") return <path key={i} transform={t} d={`M${-r} 0 A${r} ${r} 0 0 1 ${r} 0Z`} fill={q.c} />;
          if (q.k === "bar") return <rect key={i} transform={t} x={-q.s * 0.8} y={-q.s * 0.2} width={q.s * 1.6} height={q.s * 0.4} rx="3" fill={q.c} />;
          return <polygon key={i} transform={t} points={`0,${-r} ${r},${r * 0.8} ${-r},${r * 0.8}`} fill={q.c} />;
        })}
      </g>
    </g>
  );
}
function AbstractAvatar({ seed, size = 40, uid }) {
  return <svg width={size} height={size} viewBox="0 0 100 100" aria-hidden="true" style={{ flex: "none", display: "block" }}><AvInner seed={seed} cid={"avh-" + uid} /></svg>;
}
// One colour per talk; height = talk length (15 min lightning talks are the shortest cylinders).
const PAL = ["#c93a87", "#4a93a6", "#9b6fe0", "#f4620a", "#e8b020", "#3aa66b", "#e5484d", "#2f3f9e", "#ff8fb8", "#8a5a2b", "#00a8a0", "#b04ad0", "#7aa83a", "#d9468f", "#6b7c93", "#c2410c", "#0f766e", "#7c3aed", "#be123c", "#a16207", "#1d4ed8", "#15803d", "#db2777"];
const COLOR = {}; SHOWN.forEach((s, i) => { COLOR[s.id] = PAL[i % PAL.length]; });
const durMin = (t) => { const [a, b] = t.split("–").map((x) => x.trim()), m = (x) => { const r = x.match(/(\d+):(\d+)\s*(AM|PM)?/); return { h: +r[1], m: +r[2], ap: r[3] }; }, e = m(b), st = m(a), to = (o, ap) => ((o.h % 12) + (ap === "PM" ? 12 : 0)) * 60 + o.m; let d = to(e, e.ap || "PM") - to(st, st.ap || e.ap || "PM"); if (d <= 0) d += 720; return d; };
const heightOf = (s) => 0.3 + (durMin(s.time) / 60) * 3.6;
const BUILDINGS = [];
{
  const cells = {};
  SHOWN.forEach((s) => { const t = TAGS[s.id], k = t[0] + "," + t[1]; if (!cells[k]) cells[k] = []; cells[k].push(s); });
  Object.keys(cells).forEach((k) => {
    const [c, r] = k.split(",").map(Number), list = cells[k];
    list.forEach((s, i) => { const [dx, dy] = SLOTS[list.length][i], x = cellX(c) + dx, y = cellY(r) + dy; BUILDINGS.push({ s, c, r, cx: x, cy: y, hx: x, hy: y, z: 0.05, top: heightOf(s) + 0.1 }); });
  });
  for (let it = 0; it < 120; it++) {
    BUILDINGS.forEach((b, i) => {
      b.cx += (b.hx - b.cx) * 0.04; b.cy += (b.hy - b.cy) * 0.04;
      const dx = b.cx - C, dy = b.cy - C, d = Math.hypot(dx, dy) || 0.01;
      if (d < KEEP) { b.cx = C + (dx / d) * KEEP; b.cy = C + (dy / d) * KEEP; }
      if (Math.abs(b.cx - C) < 1.5) b.cx = C + (b.cx >= C ? 1.5 : -1.5);
      if (Math.abs(b.cy - C) < 1.5) b.cy = C + (b.cy >= C ? 1.5 : -1.5);
      for (let j = i + 1; j < BUILDINGS.length; j++) {
        const o = BUILDINGS[j], ex = o.cx - b.cx, ey = o.cy - b.cy, e = Math.hypot(ex, ey) || 0.01;
        if (e < 2.1) { const p = (2.1 - e) / 2; b.cx -= (ex / e) * p; b.cy -= (ey / e) * p; o.cx += (ex / e) * p; o.cy += (ey / e) * p; }
      }
      b.cx = Math.min(Math.max(b.cx, 2.4), 19.6); b.cy = Math.min(Math.max(b.cy, 2.4), 19.6);
    });
  }
}
const EMPTY = [];
for (let c = 0; c < 4; c++) for (let r = 0; r < 4; r++) if (!BUILDINGS.some((b) => b.c === c && b.r === r)) EMPTY.push([cellX(c) + CELL / 2, cellY(r) + CELL / 2]);
const COUNT = { Keynote: 0, Talk: 0, "Lightning talk": 0 };
SHOWN.forEach((s) => { COUNT[s.kind]++; });

// Position helpers: a talk\'s grid cell is read from where its building stands, so moving a building changes its tag.
const cellOf = (x, y) => [Math.min(3, Math.max(0, Math.floor((x - G0) / STEP))), 3 - Math.min(3, Math.max(0, Math.floor((y - G0) / STEP)))];
const BASE = {};
BUILDINGS.forEach((b) => { BASE[b.s.id] = [b.cx, b.cy]; });
// keep a dragged building on the island, off the plaza and roads, and clear of the others
const fitPos = (x, y, others) => {
  for (let k = 0; k < 8; k++) {
    x = Math.min(Math.max(x, 2.2), 19.8); y = Math.min(Math.max(y, 2.2), 19.8);
    const dx = x - C, dy = y - C, d = Math.hypot(dx, dy) || 0.01;
    if (d < KEEP - 0.2) { x = C + (dx / d) * (KEEP - 0.2); y = C + (dy / d) * (KEEP - 0.2); }
    if (Math.abs(x - C) < 1.5) x = C + (x >= C ? 1.5 : -1.5);
    if (Math.abs(y - C) < 1.5) y = C + (y >= C ? 1.5 : -1.5);
    others.forEach((o) => { const ex = x - o[0], ey = y - o[1], e = Math.hypot(ex, ey) || 0.01; if (e < 2.0) { x = o[0] + (ex / e) * 2.0; y = o[1] + (ey / e) * 2.0; } });
    if (!inLand(x, y, 1.5)) { x += (C - x) * 0.15; y += (C - y) * 0.15; }
  }
  return [Math.round(x * 10) / 10, Math.round(y * 10) / 10];
};
// share links: "index.x.y" per moved talk, positions in tenths of a world unit
const encodeLayout = (m) => SESSIONS.map((s, i) => (m[s.id] ? i + "." + Math.round(m[s.id][0] * 10) + "." + Math.round(m[s.id][1] * 10) : null)).filter(Boolean).join("~");
const decodeLayout = (str) => {
  const m = {};
  String(str || "").split("~").forEach((t) => { const [i, x, y] = t.split(".").map(Number); if (SESSIONS[i] && isFinite(x) && isFinite(y)) m[SESSIONS[i].id] = [Math.min(Math.max(x / 10, 2), 20), Math.min(Math.max(y / 10, 2), 20)]; });
  return m;
};
const LS_KEY = "du26-island-layout-v1";
const loadLayout = () => {
  try { const h = typeof location !== "undefined" && /[#&]l=([^&]*)/.exec(location.hash); if (h) return { m: decodeLayout(h[1]), shared: true }; } catch (e) { /* ignore */ }
  try { const j = JSON.parse(localStorage.getItem(LS_KEY) || "null"); if (j && typeof j === "object") return { m: j, shared: false }; } catch (e) { /* ignore */ }
  return { m: {}, shared: false };
};

// Summary Square: avatars of people who posted their LinkedIn summary (SAMPLE people for the mockup)
const AVATARS = [["R", "#e0674a"], ["M", "#5f9fe0"], ["K", "#5dbba8"], ["S", "#8b5fd0"], ["A", "#e7b04f"], ["N", "#e47a66"], ["J", "#4f86e8"], ["P", "#6fbfb0"], ["D", "#c46fa8"], ["V", "#7a8f4a"]]
  .map((a, i) => { const ring = i < 7 ? 3.08 : 2.28, n = i < 7 ? 7 : 3, k = i < 7 ? i : i - 7, t = (k / n) * Math.PI * 2 + (i < 7 ? 0.3 : 1.0); return { ini: a[0], col: a[1], x: C + Math.cos(t) * ring, y: C + Math.sin(t) * ring }; });

/* ---------------- static world ---------------- */
const OUTLINE = [];
{
  const arc = (cx, cy, a0, a1) => { for (let i = 0; i <= 10; i++) { const t = ((a0 + ((a1 - a0) * i) / 10) * Math.PI) / 180; OUTLINE.push([cx + RC * Math.cos(t), cy + RC * Math.sin(t)]); } };
  arc(N - RC, RC, -90, 0); arc(N - RC, N - RC, 0, 90); arc(RC, N - RC, 90, 180); arc(RC, RC, 180, 270);
}
const inLand = (x, y, m) => { const cx = Math.min(Math.max(x, RC), N - RC), cy = Math.min(Math.max(y, RC), N - RC); return x > m && x < N - m && y > m && y < N - m && Math.hypot(x - cx, y - cy) <= RC - m * 0.4; };
const blob = (cx, cy, rx, ry, k) => { const a = []; for (let t = 0; t < Math.PI * 2; t += 0.2) a.push([cx + Math.cos(t) * rx * (1 + 0.12 * Math.sin(3 * t + k)), cy + Math.sin(t) * ry * (1 + 0.1 * Math.cos(2 * t + k))]); return a; };
const circ = (cx, cy, r) => { const a = []; for (let t = 0; t < Math.PI * 2; t += 0.12) a.push([cx + Math.cos(t) * r, cy + Math.sin(t) * r]); return a; };
// colourful arrow clusters (the theme card's motif) at the four road ends, pointing in towards the Summary Square
const ARROWS = [];
[[3.4, 11, 1, 0], [18.6, 11, -1, 0], [11, 3.4, 0, 1], [11, 18.6, 0, -1]].forEach(([x, y, dx, dy]) => {
  [[0, 0, "#f05cc0"], [0.45, 0.22, "#fdaa2a"]].forEach(([al, pe, col]) => {
    const loc = [[-0.8, -0.3], [0, -0.3], [0, -0.62], [0.85, 0], [0, 0.62], [0, 0.3], [-0.8, 0.3]];
    ARROWS.push({ col, pts: loc.map(([lx, ly]) => [x + (lx + al) * dx - (ly + pe) * dy, y + (lx + al) * dy + (ly + pe) * dx]) });
  });
});
// rim lettering: [centre x, centre y, direction along the edge x, y, text]
const EDGES = [[0.95, 11, 0, 1, "TECH-LED"], [21.05, 11, 0, 1, "CRAFT-LED"], [11, 0.95, 1, 0, "FUTURE UNLOCKS"], [11, 21.05, 1, 0, "HERE & NOW"]];
