            <button type="button" className="vw" onClick={() => setFlat((f) => !f)} aria-label={flat ? "Switch to isometric view" : "Switch to top view"} title={flat ? "Isometric view" : "Top view"}>{flat ? "3D" : "TOP"}</button>
